// A CV is one page and leaves most of the work out. The portfolio usually lists
// the projects, papers and languages that answer a screening question the CV
// cannot. Strip it to plain text once per run and let both prompts read it.
const html = String($input.first().json?.data ?? $input.first().json?.body ?? '');
const text = html
  .replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<[^>]+>/g, '\n')
  .replace(/&[a-z]+;/gi, ' ')
  .split('\n').map(l => l.trim()).filter(Boolean).join('\n')
  .slice(0, 6000);

return [{ json: { portfolio_text: text || '(no portfolio content available)' } }];

// One search query per target role, paginated. MrScraper SERP costs 1 token per
// call, so this is the cheapest part of the run.
//
// Word order matters: keywords must come BEFORE `site:`. Written the other way
// round ("site:recruitee.com data scientist") the domain filter is silently
// dropped and the results are unrelated general-web pages.
const cfg     = $('Run Settings').first().json;
const profile = JSON.parse($('Load Profile').first().json.profile_json);

// Seniority belongs in the query, not only in the scoring. Searching a bare role
// name returns mostly senior and lead positions, which are then correctly
// rejected downstream, burning the whole run to reach zero results.
const LEVEL = {
  'student':    ['internship', 'junior', 'graduate'],
  'internship': ['internship', 'junior', 'graduate'],
  'entry':      ['junior', 'entry level', 'graduate'],
  'mid':        ['', 'mid level'],
  'senior':     ['senior', 'lead'],
};
const seniority = String(profile.seniority || 'mid').toLowerCase();
const levels = Object.entries(LEVEL).find(([k]) => seniority.includes(k))?.[1] ?? [''];

const roles  = (profile.target_roles || []).slice(0, cfg.MAX_ROLES);
const remote = profile.remote_ok ? 'remote ' : '';
const out    = [];

const domains = String(cfg.ATS_DOMAINS).split(',').map(d => d.trim()).filter(Boolean);

// Interleave domains so a low MAX_QUERIES still samples every ATS rather than
// spending the whole budget on the first one in the list.
for (let page = 1; page <= cfg.SERP_PAGES; page++) {
  for (const level of levels) {
    for (const domain of domains) {
      for (const role of roles) {
      out.push({ json: {
        // Keywords first, `site:` last, see the note above.
        query: `${remote}${level} ${role} site:${domain}`.replace(/\s+/g, ' ').trim(),
        page, role, level, domain,
      }});
      }
    }
  }
}
return out.slice(0, cfg.MAX_QUERIES);

// Riandra asked for fewer Code nodes, so the four steps that turn search results
// into scoring batches now live here: read the SERP hits, fetch every board's
// openings in parallel, rank them locally for free, and cut the survivors into
// batches small enough for the model to answer reliably.
//
// Each stage is still its own function, so the pipeline reads top to bottom and
// any one step can be lifted back out if it needs its own node again.
const stage1 = async (INPUT) => {

// Each ATS publishes its boards under a different URL shape. Pull the employer
// identifier out of whichever one a search result happens to be.
const PATTERNS = [
  { ats: 'recruitee',  re: /^https?:\/\/([a-z0-9][a-z0-9-]*)\.recruitee\.com/i },
  { ats: 'lever',      re: /^https?:\/\/jobs\.lever\.co\/([a-z0-9][a-z0-9-]*)/i },
  { ats: 'ashby',      re: /^https?:\/\/jobs\.ashbyhq\.com\/([a-z0-9][a-z0-9-._]*)/i },
  { ats: 'greenhouse', re: /^https?:\/\/(?:job-boards|boards)\.greenhouse\.io\/([a-z0-9][a-z0-9-_]*)/i },
];
const SKIP = new Set(['app','support','www','blog','careers','help','status','embed','api']);

const seen = new Map();
for (const item of INPUT) {
  const organic = item.json?.data?.organic ?? item.json?.organic ?? [];
  for (const r of organic) {
    const url = r.link || r.url || '';
    for (const { ats, re } of PATTERNS) {
      const m = url.match(re);
      if (!m) continue;
      const key = m[1].toLowerCase();
      if (SKIP.has(key)) break;
      seen.set(`${ats}:${key}`, { ats, board: key });
      break;
    }
  }
}

if (seen.size === 0) throw new Error('No job boards discovered, check the SERP response shape.');

// Round-robin across the four ATS before truncating, otherwise the cap is spent
// entirely on whichever provider Google happened to rank highest.
const byAts = {};
for (const v of seen.values()) (byAts[v.ats] ??= []).push(v);

const out = [];
const cap = $('Run Settings').first().json.MAX_BOARDS;
for (let i = 0; out.length < cap; i++) {
  const round = Object.values(byAts).map(list => list[i]).filter(Boolean);
  if (!round.length) break;
  for (const v of round) {
    if (out.length >= cap) break;
    out.push(v);
  }
}
return out.map(json => ({ json }));
};

const stage2 = async (INPUT) => {

// Four ATS, four payload shapes, one normalised job record.
//
// The HTTP Request node walks its input one item at a time, so thirty boards
// took five minutes and left ~22 MB of raw ATS payloads in the execution
// history. Fetching them concurrently here and keeping only the normalised
// records is around thirty times faster and an order of magnitude smaller.
//
// Only Recruitee exposes an unauthenticated endpoint for *creating* a candidate,
// so only Recruitee openings can be submitted automatically. The other three
// publish their listings openly but keep submission behind employer credentials,
// so those become assisted applications: fully researched, one tap to finish.
const strip = h => String(h || '').replace(/<[^>]+>/g, ' ')
  .replace(/&[a-z]+;/gi, ' ').replace(/\s+/g, ' ').trim();
const sub = (url, re) => (String(url || '').match(re) || [])[1];

const CONCURRENCY = 10;
const TIMEOUT = 8000;
const ENDPOINT = {
  recruitee:  b => `https://${b}.recruitee.com/api/offers/`,
  lever:      b => `https://api.lever.co/v0/postings/${b}?mode=json`,
  ashby:      b => `https://api.ashbyhq.com/posting-api/job-board/${b}`,
  greenhouse: b => `https://boards-api.greenhouse.io/v1/boards/${b}/jobs?content=true`,
};

const MAX_JOBS = 2500;   // holding every opening at once exhausts the heap

const jobs = [];
const boards = INPUT.map(i => i.json);

function collect(rows) {
  for (const o of rows) {
    let j = null;

    // ---- Recruitee -------------------------------------------------------
    if (o.slug && o.careers_apply_url) {
      if ((o.status || '').toLowerCase() !== 'published') continue;
      const board = sub(o.careers_apply_url, /^https?:\/\/([a-z0-9-]+)\.recruitee\.com/i);
      if (!board) continue;
      j = {
        ats: 'recruitee', track: 'auto', board, slug: o.slug,
        title: o.title, company: o.company_name || board,
        location: o.location || [o.city, o.country].filter(Boolean).join(', '),
        country: o.country || '', remote: !!o.remote,
        employment_type: o.employment_type_code || '', experience: o.experience_code || '',
        description: strip(o.description).slice(0, 1500),
        requirements: strip(o.requirements).slice(0, 800),
        salary: o.salary || null,
        apply_url: o.careers_apply_url,
        open_questions: (o.open_questions || []).map(q => ({
          id: q.id, body: strip(q.body), kind: q.kind, required: !!q.required,
          // `q.options` is always `{}`; the real choices live in
          // `open_question_options`. Reading the wrong one gives choice
          // questions with nothing to choose from.
          options: (q.open_question_options || []).map(x => strip(x.body)),
        })),
        needs_cv: o.options_cv === 'required',
        needs_phone: o.options_phone === 'required',
      };
    }

    // ---- Ashby -----------------------------------------------------------
    else if (o.jobUrl && o.applyUrl) {
      if (o.isListed === false) continue;
      const board = sub(o.jobUrl, /jobs\.ashbyhq\.com\/([a-z0-9._-]+)/i);
      j = {
        ats: 'ashby', track: 'assisted', board, slug: o.id,
        title: o.title, company: board,
        location: o.location || '', country: o.address?.postalAddress?.addressCountry || '',
        remote: !!o.isRemote || /remote/i.test(o.workplaceType || ''),
        employment_type: o.employmentType || '', experience: '',
        description: strip(o.descriptionPlain || o.descriptionHtml).slice(0, 1500),
        requirements: '', salary: null,
        apply_url: o.applyUrl, open_questions: [],
      };
    }

    // ---- Greenhouse ------------------------------------------------------
    else if (o.absolute_url) {
      const board = sub(o.absolute_url, /greenhouse\.io\/([a-z0-9_-]+)/i);
      const loc = o.location?.name || '';
      j = {
        ats: 'greenhouse', track: 'assisted', board, slug: String(o.id),
        title: o.title, company: o.company_name || board,
        location: loc, country: loc.split(',').pop().trim(),
        remote: /remote/i.test(loc),
        employment_type: '', experience: '',
        description: strip(o.content).slice(0, 1500),
        requirements: '', salary: null,
        apply_url: o.absolute_url, open_questions: [],
      };
    }

    // ---- Lever -----------------------------------------------------------
    else if (o.hostedUrl) {
      const board = sub(o.hostedUrl, /jobs\.lever\.co\/([a-z0-9-]+)/i);
      const loc = o.categories?.location || '';
      j = {
        ats: 'lever', track: 'assisted', board, slug: o.id,
        title: o.text, company: board,
        location: loc, country: loc.split(',').pop().trim(),
        remote: /remote/i.test(loc) || /remote/i.test(o.workplaceType || ''),
        employment_type: o.categories?.commitment || '', experience: '',
        description: strip(o.descriptionPlain || o.description).slice(0, 1500),
        requirements: '', salary: null,
        apply_url: o.applyUrl || o.hostedUrl, open_questions: [],
      };
    }

    if (!j || !j.board || !j.title) continue;
    j.job_key = `${j.ats}:${j.board}:${j.slug}`;
    j.hybrid = false;
    j.needs_cv = j.needs_cv ?? false;
    jobs.push({ json: j });
  }
}

for (let i = 0; i < boards.length; i += CONCURRENCY) {
  const payloads = await Promise.all(boards.slice(i, i + CONCURRENCY).map(async b => {
    const url = ENDPOINT[b.ats]?.(b.board);
    if (!url) return null;
    try {
      return await this.helpers.httpRequest({ url, json: true, timeout: TIMEOUT });
    } catch (e) {
      return null;   // a dead or slow board must never stall the whole run
    }
  }));
  for (const body of payloads) {
    if (!body) continue;
    collect(Array.isArray(body) ? body : (body.offers ?? body.jobs ?? []));
  }
  if (jobs.length >= MAX_JOBS) break;
}
return jobs;
};

const stage3 = async (INPUT) => {

// A free, deterministic pre-filter. Boards carry every vacancy a company has, 
// cleaners, drivers, nurses, so most openings are irrelevant to any given
// applicant. Ranking here means the LLM only ever scores plausible candidates,
// which keeps the expensive steps small.
const cfg     = $('Run Settings').first().json;
const profile = JSON.parse($('Load Profile').first().json.profile_json);

const roleWords  = (profile.target_roles || []).join(' ').toLowerCase().split(/[\s,\/]+/);
const skillWords = (profile.skills || []).map(s => s.toLowerCase());
const wanted     = [...new Set([...roleWords, ...skillWords])].filter(w => w.length > 2);

// Postings written in a language the applicant does not speak are dead ends,
// and they are common on regional boards.
const speaks = (profile.languages || []).join(' ').toLowerCase();
const foreignMarkers = {
  de: [' und ', ' der ', ' mit ', ' wir ', 'm/w/d', ' für '],
  nl: [' en ', ' van ', ' een ', ' voor ', ' wij '],
  sv: [' och ', ' att ', ' vi ', ' med '],
  fr: [' et ', ' pour ', ' nous ', ' des '],
  es: [' de la ', ' que ', ' para ', ' con ', ' desarrollador', ' experiencia'],
  it: [' della ', ' che ', ' per ', ' con il '],
  pt: [' da ', ' que ', ' para ', ' com '],
  pl: [' oraz ', ' dla ', ' jest ', ' praca '],
};

// Everything already reported on a previous run. Read once here rather than
// asking the table per opening: at ~1,000 openings a run, one query per item
// turns a two-minute execution into a stalled one.
const seen = new Set(
  $('Load Seen Jobs').all().map(r => r.json.job_key).filter(Boolean)
);

const scored = [];
for (const item of INPUT) {
  const j = item.json;
  if (seen.has(j.job_key)) continue;
  const hay = `${j.title} ${j.description} ${j.requirements}`.toLowerCase();

  // Trust the ATS `remote` flag only. Matching the word "remote" anywhere in the
  // body lets through on-site roles that merely mention a remote-work policy, 
  // they were reaching the model and being rejected for requiring a work permit.
  if (cfg.REMOTE_ONLY && j.remote !== true) continue;

  let foreign = false;
  for (const [lang, markers] of Object.entries(foreignMarkers)) {
    if (speaks.includes(lang)) continue;
    const hits = markers.filter(m => hay.includes(m)).length;
    if (hits >= 3) { foreign = true; break; }
  }
  if (foreign) continue;

  const title = String(j.title).toLowerCase();
  let score = 0;
  for (const w of wanted) {
    if (title.includes(w)) score += 5;      // title match is the strongest signal
    else if (hay.includes(w)) score += 1;
  }
  if (j.remote) score += 3;
  // Seniority mismatch is a hard exclusion, not a penalty. Without this the
  // shortlist fills with lead/principal roles that always score ~15 downstream.
  const wantsJunior = /student|intern|entry|junior|graduate/.test(String(profile.seniority || ''));
  if (wantsJunior && /senior|staff|lead\b|head of|principal|director|manager|architect|expert/.test(title)) continue;
  if (wantsJunior && /\b([5-9]|1[0-9])\+?\s*(years|jahre|yrs)/.test(hay)) continue;
  if (/intern|junior|graduate|entry|working student|trainee|apprentice/.test(title)) score += 6;

  if (score > 0) scored.push({ json: { ...j, prefilter_score: score } });
}

scored.sort((a, b) => b.json.prefilter_score - a.json.prefilter_score);

// Cap how many openings any single board contributes. One agency board posting
// forty near-identical vacancies would otherwise fill the entire shortlist and
// crowd out every other employer found that morning.
const perBoard = new Map();
const seenRole = new Set();   // one employer may run two boards with identical ads
const spread = [];
for (const row of scored) {
  const key = `${row.json.title}|${row.json.location}`.toLowerCase().replace(/\s+/g, ' ').trim();
  if (seenRole.has(key)) continue;
  seenRole.add(key);
  const b = row.json.board;
  const n = perBoard.get(b) ?? 0;
  if (n >= cfg.MAX_PER_BOARD) continue;
  perBoard.set(b, n + 1);
  spread.push(row);
  if (spread.length >= cfg.MAX_NEW_JOBS) break;
}
return spread;
};

const stage4 = async (INPUT) => {

// Score in small batches rather than one call per opening or one call for all.
//
// One call each exhausts the free-tier rate limit. One call for all twenty-five
// asks the model for a JSON array so long that it drifts or truncates, and the
// parser then rejects the whole reply: a run that shortlisted 25 scored 1.
// Batches of six are short enough to come back well-formed and still let the
// model weigh the openings in a batch against each other.
const BATCH = 4;
const jobs = INPUT.map(i => ({
  job_key:    i.json.job_key,
  title:      i.json.title,
  company:    i.json.company,
  location:   i.json.location,
  remote:     i.json.remote,
  seniority:  i.json.experience,
  employment: i.json.employment_type,
  description:  String(i.json.description  || '').slice(0, 1200),
  requirements: String(i.json.requirements || '').slice(0, 800),
}));
const batches = [];
for (let i = 0; i < jobs.length; i += BATCH) {
  const slice = jobs.slice(i, i + BATCH);
  batches.push({ json: { openings: JSON.stringify(slice, null, 1), count: slice.length } });
}
return batches;
};

let data = $input.all();
data = await stage1(data);   // SERP hits  -> company boards
const boards = data.length;
data = await stage2(data);   // boards     -> normalised openings
const scanned = data.length;
data = await stage3(data);   // openings   -> ranked shortlist
const shortlist = data;
data = await stage4(data);   // shortlist  -> scoring batches

// Carry the shortlist along so the scoring step can pair verdicts back to jobs
// without a separate node to read from. boards and scanned ride along too: they
// are the only record of how much was actually read, and the digest reports them
// so the shortlist can be judged against the pile it came from.
return data.map(b => ({ json: { ...b.json, jobs: shortlist.map(x => x.json), boards, scanned } }));

