// Expand the single batched verdict back into one item per opening, joined on job_key.
// One item per batch comes back, so merge every batch's verdicts into one map.
const byKey = new Map();
for (const item of $input.all()) {
  const out = item.json.output ?? item.json;
  for (const r of (out.results || [])) byKey.set(r.job_key, r);
}

return $('Find And Shortlist').all()[0].json.jobs.map(j => ({ json: j })).map(item => {
  const m = byKey.get(item.json.job_key) ?? {
    match_score: 0, verdict: 'skip', blockers: ['not scored'],
    strengths: [], gaps: [], seniority_fit: 'under',
  };
  return { json: { ...item.json, match: m, match_score: m.match_score ?? 0 } };
});

// Two research questions per surviving opening. Both need pages that have no API
// behind them, which is exactly what the scraper is for.
//
// Salary is cached on role+country because the market rate for "data analyst in
// Germany" does not change per employer, without this the same lookup is paid
// for on every run.
const cache = new Map(
  $('Load Salary Cache').all().map(r => [r.json.cache_key, r.json])
);

// Read the openings explicitly: this node's own input is the cache lookup above.
const cfg  = $('Run Settings').first().json;
const jobs = $('Worth Applying').all().slice(0, cfg.MAX_ENRICH);

const out = [];
for (const item of jobs) {
  const j = item.json;
  // Salary sites index canonical role names. A raw posting title, 
  // "Machine Learning Intern/Co-op (Winter 2027)", matches nothing, so strip
  // the seasons, years, contract shapes and punctuation down to the role itself.
  const role = String(j.title)
    .replace(/\(.*?\)/g, ' ')
    .replace(/\b(winter|spring|summer|fall|autumn)\b/gi, ' ')
    .replace(/\b20\d\d\b/g, ' ')
    .replace(/\b(co[- ]?op|contract|part[- ]time|full[- ]time|remote|hybrid|m\/f\/x|m\/w\/d)\b/gi, ' ')
    .replace(/[^a-zA-Z ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .split(' ').slice(0, 4).join(' ');

  const country = (j.country || 'United States').replace(/\(.*?\)/g, '').trim() || 'United States';
  const key     = `${role}|${country}`.toLowerCase();

  // Each research question is individually switchable: extraction is the only
  // metered step here, and page weight makes its cost hard to predict.
  if (cfg.WITH_SALARY && !cache.has(key)) {
    out.push({ json: { job_key: j.job_key, kind: 'salary', cache_key: key, company: j.company,
                       query: `${role} salary ${country} site:levels.fyi OR site:glassdoor.com` } });
  }
  if (cfg.WITH_REVIEWS) {
    // Company names collide badly, "Cohere" the AI lab vs "Cohere Health".
    // Anchoring on the careers domain the posting actually came from keeps the
    // search on the right employer.
    const domain = (j.apply_url.match(/^https?:\/\/([^/]+)/) || [])[1] || '';
    out.push({ json: { job_key: j.job_key, kind: 'reviews', cache_key: key, company: j.company,
                       query: `"${j.company}" employee reviews glassdoor OR indeed`,
                       hint: domain } });
  }
}
return out;

// Prefer sources that actually publish the numbers we want.
// Ordered by extraction cost, cheapest first, page weight drives token spend far
// more than anything else. levels.fyi cost 31 tokens; Glassdoor cost 224.
const PREFER = {
  salary:  ['levels.fyi/t/', 'payscale.com', 'salaryexpert.com', 'glassdoor.com/Salaries/'],
  reviews: ['glassdoor.com/Reviews/', 'indeed.com/cmp/', 'kununu.com', 'comparably.com'],
};
// Pages that match the domain but answer a different question.
const REJECT = {
  salary:  ['/Job/', '/jobs', '/job-listing', 'indeed.com/q-', 'linkedin.com'],
  reviews: ['/salary', '/Salaries/', 'linkedin.com'],
};

const plan = $('Plan Enrichment').all();
const out  = [];

$input.all().forEach((item, i) => {
  const meta    = plan[i]?.json ?? {};
  const organic = item.json?.data?.organic ?? [];
  const wanted  = PREFER[meta.kind] ?? [];
  const banned  = REJECT[meta.kind] ?? [];

  const ok = r => {
    const u = r.link || '';
    return u && !banned.some(b => u.includes(b));
  };

  // Take the highest-preference source available, in order.
  let chosen = null;
  for (const domain of wanted) {
    chosen = organic.find(r => ok(r) && (r.link || '').includes(domain));
    if (chosen) break;
  }

  // No recognised source: skip rather than extract from whatever ranked first.
  // A company's own homepage carries no salary table and no reviews, and paying
  // 200+ tokens to discover that is the worst outcome available.
  if (!chosen) return;

  out.push({ json: { ...meta, url: chosen.link, source_title: chosen.title || '' } });
});

// Emitting nothing would stop the run dead: every later node, including the
// digest, simply never executes. If no recognised source turned up, fall back to
// the best result for the first plan entry so the chain always has one item.
if (!out.length) {
  const first = plan[0];
  const organic = $input.first()?.json?.data?.organic ?? [];
  const usable = organic.find(r => r.link && !/linkedin\.com/.test(r.link));
  if (first && usable) {
    out.push({ json: { ...first, url: usable.link, source_title: usable.title || '', fallback: true } });
  }
}
return out;

// Riandra asked for fewer Code nodes: folding the extraction results back onto
// their openings and choosing which of them get a cover letter are two steps of
// one job, so they run here together.
const foldEnrichment = (INPUT) => {

// Fold the finished extractions back onto their openings, and reuse anything
// already sitting in the salary cache.
// Match each finished extraction to its plan entry by URL, not by position. The
// polling loop sends items round again until they finish, so arrival order stops
// matching the order they were requested in, and pairing by index silently
// attached every result to the wrong opening.
const plan  = $('Pick Best Source').all().map(i => i.json);
const byUrl = new Map(plan.map(p => [p.url, p]));
const cache = new Map($('Load Salary Cache').all().map(r => [r.json.cache_key, r.json]));

const salary  = new Map();
const reviews = new Map();

INPUT.forEach((item, i) => {
  const res  = item.json?.data ?? item.json;
  const meta = byUrl.get(res.url) ?? plan[i] ?? {};
  if ((res.status || '') !== 'Finished' || !res.data) return;
  if (meta.kind === 'salary') {
    // Extractions come back as either flat fields or a nested `salary_range`.
    // Field names drift between pages: one reply used `minimum_salary_usd` with
    // nulls and put the real figure in `average_total_compensation_usd`, which a
    // strict lookup threw away. Take whatever the reply actually carries.
    const d = res.data, r = d.salary_range ?? d;
    const num = v => { const n = Number(String(v ?? '').replace(/[^\d.]/g, '')); return Number.isFinite(n) && n > 0 ? n : 0; };
    const pick = (...pats) => {
      for (const [k, v] of Object.entries(r)) {
        if (pats.some(p => k.toLowerCase().includes(p)) && num(v)) return num(v);
      }
      return 0;
    };
    let lo = pick('minimum', 'min_', 'min salary', 'low');
    let hi = pick('maximum', 'max_', 'max salary', 'high');
    // A single figure is still worth showing; treat it as both ends.
    if (!lo && !hi) { const one = pick('typical', 'average', 'median', 'total_comp'); lo = hi = one; }
    if (lo || hi) {
      salary.set(meta.cache_key, {
        minimum: lo, maximum: hi,
        currency: r.currency || d.currency || '',
        period: r.period || d.period || 'year',
        source_url: meta.url,
      });
    }
  }
  if (meta.kind === 'reviews') reviews.set(meta.job_key,  { ...res.data, source_url: meta.url });
});

return $('Worth Applying').all().map(item => {
  const j   = item.json;
  const key = `${String(j.title).replace(/\(.*?\)/g,'').replace(/[^a-zA-Z ]/g,' ').trim()}|${j.country || 'remote'}`.toLowerCase();
  const cached = cache.get(key);
  return { json: { ...j,
    cache_key: key,
    salary_estimate: salary.get(key) ?? ((cached && (cached.salary_min || cached.salary_max)) ? {
      minimum: cached.salary_min, maximum: cached.salary_max,
      currency: cached.currency, period: cached.period, source_url: cached.source_url,
    } : null),
    salary_is_fresh: salary.has(key),
    company_reviews: reviews.get(j.job_key) ?? null,
  }};
});
};

const pickForLetters = (INPUT) => {

// A cover letter costs one model call each, so only a few get one. Openings that
// can actually be submitted come first: a letter is what makes an application
// possible, and picking purely by score let un-appliable listings crowd out the
// only kind the workflow can send, leaving nothing to apply to.
// Letters are what make an application possible, so this cap has to leave room
// for every opening the run might apply to. Capping at MAX_ENRICH alone silently
// made MAX_APPLY unreachable: only one opening ever had a letter, so only one
// could ever be submitted no matter how high MAX_APPLY was set.
const cfg = $('Run Settings').first().json;
const cap = Math.max(cfg.MAX_ENRICH, cfg.MAX_APPLY);
return INPUT
  .sort((a, b) => {
    const submittable = x => (x.json.track === 'auto' && !x.json.blocked) ? 1 : 0;
    return submittable(b) - submittable(a) || b.json.match_score - a.json.match_score;
  })
  .slice(0, cap);
};

const enriched = foldEnrichment($input.all());
const drafting = pickForLetters(enriched);

// Every enriched opening travels with the shortlist so the digest can still list
// the ones that did not get a letter, without another node to read them from.
return drafting.map(d => ({ json: { ...d.json, _all: enriched.map(e => e.json) } }));

// A morning with no match used to send nothing at all, which is
// indistinguishable from the workflow being broken. Say so instead.
//
// This sits on the discarded branch, which also fires on days when other
// openings did pass, so it stays quiet unless the kept branch is empty.
// An IF node has two outputs, and `.all()` without an index does not
// distinguish them: reading it that way saw the discarded items and stayed
// silent on exactly the mornings this message exists for. Index 0 is the
// kept branch, and it throws rather than returning [] when nothing passed.
let kept = [];
try { kept = $('Worth Applying').all(0); } catch (e) { kept = []; }
if (kept.length) return [];

const best = $input.all()
  .map(i => i.json)
  .sort((a, b) => b.match_score - a.match_score)[0];
const floor = $('Run Settings').first().json.MIN_MATCH_SCORE;

return [{ json: { text:
  `Nothing worth applying to today.\n\n`
  + `${$input.all().length} openings were read and scored. `
  + (best ? `The closest was ${best.title} at ${best.company}, scoring ${best.match_score} against a floor of ${floor}.` : '')
  + `\n\nLower MIN_MATCH_SCORE in Run Settings if you want to see more.` }}];

