// Two different failures, handled differently.
//
// A *hard blocker*, a work permit, a language, a seniority gap, means the
// application cannot honestly be made at all. Those are dropped here.
//
// A *low-confidence answer* means the model produced a plausible answer that the
// CV does not evidence: a knowledge quiz, a question about preferences. Those are
// not for the workflow to decide. They are carried forward and shown at the
// approval step, so the applicant reads them and takes responsibility, which is
// the entire point of having a human in the loop.
const jobs = $('Prepare Drafts').all();

return $input.all().map((item, i) => {
  const job   = jobs[i].json;
  const draft = item.json.output ?? item.json;
  const byId  = new Map((draft.answers || []).map(a => [a.open_question_id, a]));

  const unanswerable = [];
  const needsReview  = [];

  for (const q of job.open_questions || []) {
    if (!q.required) continue;
    const a = byId.get(q.id);
    const empty = !a || (q.kind === 'boolean' ? a.flag === undefined || a.flag === null
                                              : !String(a.content || '').trim());
    if (empty) { unanswerable.push(q.body.slice(0, 80)); continue; }
    if (a.confident === false) {
      needsReview.push({
        question: q.body.slice(0, 110),
        answer: q.kind === 'boolean' ? (a.flag ? 'Yes' : 'No') : a.content,
      });
    }
  }

  const reasons = [];
  if ((job.match?.blockers || []).length) reasons.push(job.match.blockers.join('; '));
  if (unanswerable.length) reasons.push('no answer possible for: ' + unanswerable.join(' | '));

  // A model that has been told not to use em dashes still uses them. Scrub the
  // generated text rather than trusting the instruction.
  const clean = t => String(t ?? '')
    .replace(/\s*[\u2014\u2013]\s*/g, ', ')   // em and en dash, as escapes so a find-and-replace cannot mangle the class
    .replace(/\bI am writing to apply\b/gi, 'I would like to apply')
    .replace(/\bI am excited to\b/gi, 'I would like to')
    .replace(/\bleverage\b/gi, 'use')
    .replace(/\bdelve into\b/gi, 'work on')
    .replace(/\brobust\b/gi, 'reliable')
    .replace(/\bseamless(ly)?\b/gi, 'smooth')
    .replace(/\bcutting[- ]edge\b/gi, 'new')
    .replace(/\butili[sz]e\b/gi, 'use')
    .replace(/\bactionable\b/gi, 'useful')
    .replace(/,\s*,/g, ',')
    .trim();

  draft.cover_letter    = clean(draft.cover_letter);
  draft.salary_verdict  = clean(draft.salary_verdict);
  draft.culture_summary = clean(draft.culture_summary);
  for (const a of draft.answers || []) a.content = clean(a.content);

  return { json: { ...job, draft,
    blocked: reasons.length > 0,
    blocked_reason: reasons.join(', '),
    needs_review: needsReview }};
});

const cfg = $('Run Settings').first().json;

// Openings that were scored but not drafted still belong in the digest. Without
// this, raising MAX_NEW_JOBS would widen the search and narrow the report.
const drafted = new Map($input.all().map(i => [i.json.job_key, i.json]));
const all = ($('Prepare Drafts').all()[0]?.json?._all ?? []).map(j => ({ json: j })).map(i => {
  const d = drafted.get(i.json.job_key);
  return d ? { json: d } : { json: { ...i.json,
    draft: { cover_letter: '', answers: [], salary_verdict: 'no data',
             culture_summary: i.json.company_reviews ? '' : 'no reviews found' },
    blocked: false, blocked_reason: '', needs_review: [], letter_pending: true }};
});
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

return all.map(item => {
  const j = item.json, d = j.draft, s = j.salary_estimate;
  // "USD 87+1234567890 per yearly" reads like a machine wrote it.
  const num = n => Number(n).toLocaleString('en-US');
  const per = { yearly: 'a year', monthly: 'a month', hourly: 'an hour',
                year: 'a year', month: 'a month', hour: 'an hour' };
  const money = s && (s.minimum || s.maximum)
    ? [s.currency, `${num(s.minimum || s.maximum)}${s.minimum && s.maximum ? ' to ' + num(s.maximum) : ''}`,
       per[String(s.period || '').toLowerCase()] || ''].filter(Boolean).join(' ')
    : '';

  let route;
  if (j.blocked)              route = 'needs_you';
  else if (j.track !== 'auto') route = 'one_tap';
  else if (cfg.DRY_RUN)        route = 'dry_run';
  else                         route = 'submitted';

  // Compose the approval message here rather than in an n8n expression: nested
  // quotes and newlines inside `{{ }}` are fragile and fail as "invalid syntax".
  const lines = [
    'Apply to this one?', '',
    j.title,
    `${j.company} · ${j.location}`,
    `Match ${j.match_score}/100`,
  ];
  if (money) lines.push(money);
  if (d.culture_summary && d.culture_summary !== 'no reviews found') lines.push('', d.culture_summary);
  if ((j.needs_review || []).length) {
    lines.push('', 'Check these before approving, your CV does not evidence them:');
    for (const r of j.needs_review) lines.push(`· ${r.question}`, `  → ${r.answer}`);
  }
  lines.push('', 'Cover letter:', d.cover_letter);

  return { json: { ...j, route, money, culture: d.culture_summary,
                   pay_note: d.salary_verdict, approval_text: lines.join('\n') } };
});

// Best first, then cap. `Send and Wait` pauses the whole execution for a single
// question, so the loop below asks about one opening at a time; MAX_APPLY is
// what decides how many rounds that loop runs.
const cap = $('Run Settings').first().json.MAX_APPLY;
return $input.all()
  .sort((a, b) => b.json.match_score - a.json.match_score)
  .slice(0, cap);

