// Say what actually happened. A silent success is indistinguishable from a
// silent failure, and this one ends with a real application under a real name.
const job = $('Apply Loop').first().json;
const res = $input.first().json ?? {};
const ok  = !res.error && (res.candidate?.id || res.id);

const lines = ok
  ? ['Application sent.', '',
     job.title,
     `${job.company} · ${job.location}`,
     res.candidate?.id ? `Reference ${res.candidate.id}` : '',
     '', 'Your CV and answers are with them now.']
  : ['Could not send that application.', '',
     job.title,
     `${job.company} · ${job.location}`,
     '',
     'Reason: ' + (Array.isArray(res.error) ? res.error.join('; ') : String(res.error || 'unknown')),
     '', `Apply yourself here: ${job.apply_url}`];

return [{ json: { text: lines.filter(l => l !== '').join('\n'), ok,
                  job_key: job.job_key,
                  submit_status: ok ? 'submitted' : 'declined' } }];

const job = $('Apply Loop').first().json;
return [{ json: { job_key: job.job_key, submit_status: 'declined', text: [
  'Skipped, nothing sent.', '',
  job.title,
  `${job.company} · ${job.location}`,
  '',
  `Still open if you change your mind: ${job.apply_url}`,
].join('\n') } }];

// One row per opening the run touched, whichever branch it came down. The table
// doubles as the dedupe memory for tomorrow's run.
const cfg = $('Run Settings').first().json;

// A branch that never ran throws on lookup, so every cross-node read is guarded.
const safeAll = (name) => { try { return $(name).all(); } catch (e) { return []; } };

// `Ask Approval` answers line up with the openings it was given, one for one.
// Matching against the POST results instead compares two lists of different
// lengths and files a successful application as declined.
// Each pass of the loop tags its own opening, so the merged input carries one
// settled verdict per attempt. Reading the branch nodes directly would only ever
// show the final pass.
const submitted = new Set();
const declined  = new Set();
for (const item of $input.all()) {
  const j = item.json;
  if (!j?.job_key) continue;
  if (j.submit_status === 'submitted') submitted.add(j.job_key);
  if (j.submit_status === 'declined')  declined.add(j.job_key);
}

return $('Build Card').all().map(item => {
  const j = item.json;
  let status;
  if (j.blocked)            status = 'blocked';
  else if (j.track !== 'auto') status = 'one_tap';
  else if (cfg.DRY_RUN)     status = 'dry_run';
  else if (submitted.has(j.job_key)) status = 'submitted';
  else if (declined.has(j.job_key))  status = 'declined';
  else                      status = 'queued';   // ranked below today's pick

  return { json: {
    job_key: j.job_key, board: j.board, slug: j.slug,
    title: j.title, company: j.company, apply_url: j.apply_url,
    match_score: j.match_score,
    track: j.track === 'auto' ? `${j.ats}-auto` : `${j.ats}-assisted`,
    status,
    notes: (j.blocked_reason || j.draft?.salary_verdict || '').slice(0, 400),
  }};
});

// One message per run. No emoji, no telemetry, no filler, this lands on a
// phone at 8am and should read like a colleague sent it.
const cards = $('Build Card').all().map(i => i.json);
const esc = t => String(t ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

const group = r => cards.filter(c => c.route === r);
const submitted = group('submitted');
const oneTap    = [...group('one_tap'), ...group('dry_run')];
const needsYou  = group('needs_you');

const entry = c => {
  const bits = [esc(c.company), esc(c.location)].filter(Boolean).join(' · ');
  const pay  = c.money ? `\n     ${esc(c.money)}` : '';
  return `<b>${c.match_score}</b> · <a href="${esc(c.apply_url)}">${esc(c.title)}</a>\n     ${bits}${pay}`;
};

const parts = [];
const total = cards.length;
// A count on its own says nothing. Two out of nine hundred is a filter working;
// two out of three is a filter that found almost nothing to read.
const scan  = $('Find And Shortlist').first().json || {};
const drawn = scan.scanned
  ? `\n<i>from ${Number(scan.scanned).toLocaleString('en-US')} openings on ${scan.boards} company boards</i>`
  : '';
parts.push(`<b>${total} role${total === 1 ? '' : 's'} worth your time today</b>${drawn}`);

if (submitted.length) {
  parts.push(`\n<b>Applied for you</b>\n` + submitted.map(entry).join('\n\n'));
}
if (oneTap.length) {
  parts.push(`\n<b>Ready to send, one tap</b>\n` + oneTap.map(entry).join('\n\n'));
}
if (needsYou.length) {
  parts.push(`\n<b>Needs an answer only you can give</b>\n`
    + needsYou.map(c => `${entry(c)}\n     <i>${esc(String(c.blocked_reason).slice(0, 130))}</i>`).join('\n\n'));
}

const top = cards.slice().sort((a, b) => b.match_score - a.match_score)[0];
if (top?.culture && top.culture !== 'no reviews found') {
  parts.push(`\n<b>On ${esc(top.company)}</b>\n<i>${esc(top.culture)}</i>`);
}

// Telegram caps a message at 4096 characters; split on section boundaries.
const LIMIT = 3800;
const chunks = [];
let buf = '';
for (const part of parts) {
  if ((buf + part).length > LIMIT && buf) { chunks.push(buf); buf = ''; }
  buf += (buf ? '\n' : '') + part;
}
if (buf) chunks.push(buf);

return chunks.map(text => ({ json: { text } }));

// Persist only benchmarks fetched this run; cached ones are already stored.
const rows = [];
for (const item of ($('Prepare Drafts').all()[0]?.json?._all ?? []).map(j => ({ json: j }))) {
  const j = item.json, s = j.salary_estimate;
  if (!j.salary_is_fresh || !s) continue;
  const lo = Number(s.minimum ?? s.salary_range?.minimum) || 0;
  const hi = Number(s.maximum ?? s.salary_range?.maximum) || 0;
  if (!lo && !hi) continue;   // extraction found no figures, do not poison the cache
  if (rows.some(r => r.cache_key === j.cache_key)) continue;
  rows.push({
    cache_key: j.cache_key,
    role: j.title, country: j.country || 'remote',
    currency: s.currency || s.salary_range?.currency || '',
    period: s.period || s.salary_range?.period || '',
    salary_min: lo, salary_max: hi,
    median: Number(s.median || s.median_total_compensation) || 0,
    source_url: s.source_url || '',
  });
}
return rows.map(json => ({ json }));
